            sb.Append("[QualityScorecard] Next focus: ");
            for (var i = 0; i < lowest.Count; i++)
            {
                if (i > 0) sb.Append(", ");
                sb.Append(lowest[i].Label).Append('=').Append(lowest[i].Score);
            }

            sb.AppendLine();
            var parity = overall >= GalaxyParity && AllAtLeast(pillars, GalaxyParity) && humanFeel;
            sb.AppendLine(parity
                ? "[QualityScorecard] PARITY MET"
                : "[QualityScorecard] PARITY NOT MET — keep iterating lowest pillars");
            Debug.Log(sb.ToString());

            if (Application.isBatchMode)
            {
                EditorApplication.Exit(parity ? 0 : 2);
            }
