        private static List<Pillar> BuildPillars()
        {
            var list = new List<Pillar>();

            // Controls / feel
            var apexHang = FileContains("Brief apex hang") || FileContains("gravity *= 0.72f");
            var softFall = FileContains("Soft terminal fall") || FileContains("maxFall = -28f");
            list.Add(Score(
                "controls", "Controls / feel", 96,
                Exists("Assets/SpaceAndCrafts/Scripts/Player/SplatMotor.cs") ? 30 : 0,
                Exists("Assets/SpaceAndCrafts/ScriptableObjects/SplatMotorSettings.asset") ? 18 : 0,
