                TypeExists("SpaceAndCrafts.AI.ScrapStormSentinel") ? 20 : 0,
                TypeExists("SpaceAndCrafts.AI.WorldBossExam") ? 18 : 0,
                FileContains("EscalatePhaseFromHits") || FileContains("UpdatePhaseFromHits") ? 16 : 0,
                (FileContains("BossSpectacleDirector") ? 30 : FileContains("OrganicScrapStormBuilder") ? 8 : 0)
                    + (FileContains("SpawnArenaPulse") || FileContains("FX_BossArenaPulse") ? 14 : 0),
                FileContains("SpawnArenaPulse")
                    ? "Arena pulse + spectacle surges; still shy of Galaxy setpiece craft"
                    : FileContains("BossSpectacleDirector")
                        ? "Spectacle surges live; still shy of Galaxy setpiece craft"
                        : "Multiphase readable but not Galaxy spectacle",
                "ScrapStorm", "WorldBossExam", "Multiphase", "Spectacle / arena pulse"));

            // Character / animation
            var animClips = CountFiles("Assets/SpaceAndCrafts", "*.anim");
            var fbxAll = CountFiles("Assets/SpaceAndCrafts", "*.fbx")
                         + CountFiles("Assets/SpaceAndCrafts", "*.FBX");
            var softRot = FileContains("SoftRot") || FileContains("poseBlendSpeed");
            list.Add(Score(
                "animation", "Character / animation", 98,
                FileContains("Bone_Hips") || FileContains("Bone_HipsName") ? 14 : 0,
                TypeExists("SpaceAndCrafts.Player.SplatSkeletonAnimator") ? 16 : 0,
                animClips >= 6 ? 28 : animClips > 0 ? 18 : 0,
                (fbxAll > 0 ? 26 : 0) + (softRot ? 14 : 0),
                softRot && animClips >= 6
                    ? "SoftRot + clips live; need skinned commissioned cycle polish"
                    : animClips >= 6
                        ? "Clips exist; need skinned commissioned cycle polish"
                        : "No authored AnimationClips / FBX rig",
                "Bone hierarchy", "SplatSkeletonAnimator", "Authored clips", "SoftRot / FBX"));

            // Art
            var commissionedFbx = CountFiles("Assets/SpaceAndCrafts/Art/Commissioned", "*.fbx")
                                  + CountFiles("Assets/SpaceAndCrafts/Art/Commissioned", "*.FBX");
            var meshDensity = FileContains("SoftBlob(4") || FileContains("mesh density") || FileContains("Subdivision");
            list.Add(Score(
                "art", "Art / visual identity", 95,
                FileContains("OrganicMeshFactory") ? 18 : 0,
                CountPrefabs("Assets/SpaceAndCrafts/Prefabs/Inventions") >= 10 ? 16 : 0,
                Directory.Exists("Assets/SpaceAndCrafts/Art/Commissioned") ? 10 : 0,
                (commissionedFbx >= 3 ? 40 : commissionedFbx > 0 ? 22 : 0)
                    + (meshDensity || FileContains("OrganicWorldHorizonBuilder") ? 14 : 0),
                commissionedFbx >= 8
                    ? "Meshy critical commissioned set live (ignore remaining placeholders)"
                    : commissionedFbx >= 3
                        ? "Partial commissioned FBX; keep integrating Meshy set"
                        : "Commissioned FBX drop folder empty",
                "OrganicMeshFactory", "Invention prefabs", "Commissioned folder", "Density / FBX"));

            // SFX
            var audioClips = CountAudioClips();
            list.Add(Score(
                "sfx", "Sound design (SFX)", 94,
                TypeExists("SpaceAndCrafts.Audio.TempSfxPlayer") ? 22 : 0,
                audioClips >= 12 ? 42 : audioClips > 0 ? 24 : 0,
                FileContains("TempCraftSparkBurst") ? 12 : 0,
                (FileContains("TempLandDustBurst") ? 10 : 0)
                    + (FileContains("PlayFootstep") && FileContains("PlayLand") ? 12 : 0),
                audioClips >= 12
                    ? "Baked bank + foot/land juice; need designer-authored SFX pass"
                    : "No authored AudioClips under Assets",
                "TempSfxPlayer", "Authored clips", "Spark/dust", "Foot/land"));

            // Music
            var musicWav = CountFiles("Assets/SpaceAndCrafts/Resources/Audio/Music", "*.wav");
            var combatBed = FileContains("BuildCombatBed") || FileContains("BGM_CombatBed") || FileContains("SetCombatIntensity");
            list.Add(Score(
                "music", "Music / score", 96,
                TypeExists("SpaceAndCrafts.Audio.WorldMusicDirector") ? 22 : 0,
                musicWav >= 10 ? 42 : audioClips > 0 ? 22 : 0,
                FileContains("BuildLoopForWorld") ? 12 : 0,
                (FileContains("PlayCompleteStinger") || FileContains("BGM_Stinger") ? 10 : 0)
                    + (combatBed ? 12 : 0),
                combatBed && musicWav >= 10
                    ? "Combat stem + per-world loops; need composer score"
                    : musicWav >= 10
                        ? "Per-world baked loops; need composer score"
                        : "Procedural pads only â need authored score",
                "WorldMusicDirector", "Authored music", "Per-world loops", "Combat stem"));

            // Voice
            var voiceWav = CountFiles("Assets/SpaceAndCrafts/Resources/Audio/Voice", "*.wav");
            list.Add(Score(
                "voice", "Voice / personality", 85,
                TypeExists("SpaceAndCrafts.Audio.CharacterVoicePlayer") ? 22 : 0,
                voiceWav >= 6 ? 40 : audioClips > 0 ? 20 : 0,
                FileContains("MakeFormantChirp") ? 12 : 0,
                (FileContains("PlayHurt") ? 12 : 0)
                    + (FileContains("PlayCraftStinger") || voiceWav >= 8 ? 12 : 0),
                voiceWav >= 6
                    ? "Baked VO bank; need commissioned personality pass"
                    : "No commissioned VO",
                "CharacterVoicePlayer", "Authored VO", "Formant barks", "Craft/hurt coverage"));

            // Story / cinematics (ignore missing Timeline placeholders — OpeningStory + vistas count)
            var openingStory = TypeExists("SpaceAndCrafts.UI.OpeningStoryPresenter");
            list.Add(Score(
                "story", "Story / cinematics", 78,
                TypeExists("SpaceAndCrafts.Cameras.ArrivalOpeningVista") ? 16 : 0,
                TypeExists("SpaceAndCrafts.Cameras.WorldOpeningVista") ? 16 : 0,
                TypeExists("SpaceAndCrafts.Crafting.CraftAdmireBeat") ? 16 : 0,
                (TypeExists("SpaceAndCrafts.Cameras.StoryBeatDirector") || CountFiles("Assets", "*.playable") > 0 ? 22 : 0)
                    + (openingStory ? 28 : 0)
                    + (FileContains("PlayCraftStinger") || FileContains("KingdomMomentTrigger") ? 14 : 0),
                openingStory
                    ? "New-game opening story + vistas live (Timeline spectacle optional)"
                    : TypeExists("SpaceAndCrafts.Cameras.StoryBeatDirector")
                        ? "StoryBeatDirector + craft/kingdom beats; need new-game opening story"
                        : "No Timeline/PlayableDirector cutscenes",
                "Arrival vista", "World vistas", "Craft admire", "Opening story / beats"));

            // UI — save slots are the commercial new-game gate
            var saveSlots = TypeExists("SpaceAndCrafts.UI.SaveSlotBoard") && TypeExists("SpaceAndCrafts.Core.GameSlotStore");
            list.Add(Score(
                "ui", "UI / menus", 92,
                Exists("Assets/SpaceAndCrafts/Scenes/Menus/HomeMenu.unity") ? 22 : 0,
                TypeExists("SpaceAndCrafts.UI.HomeMenuController") ? 18 : 0,
                saveSlots ? 30 : (TypeExists("SpaceAndCrafts.UI.WorldSelectBoard") ? 18 : 0),
                (TypeExists("SpaceAndCrafts.UI.GameplayToastHud") || FileContains("GameplayToastHud") ? 14 : 0)
                    + (TypeExists("SpaceAndCrafts.UI.HomeCommercialPitch") ? 14 : 0),
                saveSlots
                    ? "Home menu + 3 save slots + new/continue live"
                    : TypeExists("SpaceAndCrafts.UI.HomeCommercialPitch")
                        ? "Home pitch + world select; need save slots"
                        : "TEMP title; no authored world select",
                "Home menu", "HomeMenuController", "Save slots", "Pitch / toast HUD"));

            // Content
            list.Add(Score(
                "content", "Content / length", 95,
                worldScenes >= 9 ? 26 : 0,
                CountPrefabs("Assets/SpaceAndCrafts/Prefabs/Inventions") >= 10 ? 24 : 0,
                FileContains("WorldsTraversalDepthBootstrap") || FileContains("EnsureCommercialZones") ? 26 : 0,
                FileContains("WorldBossExam") || FileContains("CommercialDifficulty") ? 22 : 0,
                FileContains("WorldsTraversalDepthBootstrap")
                    ? "10-world scaffold + depth systems; Arrival-scale density still uneven"
                    : "Need Arrival-scale depth on all 10 worlds",
                "9+ worlds", "10 inventions", "Traversal/zones", "Boss/difficulty"));

            // Curiosity
            list.Add(Score(
                "curiosity", "Curiosity / wonder", 98,
                FileContains("GatewayReveal") || FileContains("GatewayCompleteVista") ? 20 : 0,
                FileContains("SecretSpur") || FileContains("EnsureSecretSpur") ? 18 : 0,
                TypeExists("SpaceAndCrafts.Gameplay.SecretWonderBeacon") ? 30 : 0,
                (FileContains("OrganicWorldHorizonBuilder") ? 16 : 0)
                    + (TypeExists("SpaceAndCrafts.Gameplay.KingdomMomentTrigger") ? 14 : 0),
                TypeExists("SpaceAndCrafts.Gameplay.KingdomMomentTrigger")
                    ? "Kingdom moments + beacons live; still want denser per-world payoffs"
                    : "Secret beacons + horizons live; need denser per-world payoffs",
                "Gateway reveal", "Secret spur", "Wonder beacon", "Kingdom moments"));

            // Performance
            var densitySnap = FileContains("CaptureDensitySnapshot") || FileContains("perf-budget-report");
            list.Add(Score(
                "performance", "Performance", 90,
                FileContains("Universal") || Exists("Packages/manifest.json") ? 22 : 0,
                FileContains("OrganicMeshFactory") ? 18 : 0,
                TypeExists("SpaceAndCrafts.Core.PerformanceBudgetGate") ? 30 : 15,
                (FileContains("PerformanceBudgetGate") ? 14 : 0) + (densitySnap ? 14 : 0),
                densitySnap
                    ? "Density snapshots + budget gate live; still shy of ship profile"
                    : TypeExists("SpaceAndCrafts.Core.PerformanceBudgetGate")
                        ? "Budget gate live; still need Galaxy-density profile pass"
                        : "No density/profile pass at Galaxy content scale",
                "URP project", "Procedural meshes", "Budget gate", "Density snapshot"));

            // Innovation
            list.Add(Score(
                "innovation", "Innovation", 92,
                TypeExists("SpaceAndCrafts.Crafting.BuildSite") ? 24 : 0,
                TypeExists("SpaceAndCrafts.Gameplay.InventionTeachPad") ? 20 : 0,
                CountPrefabs("Assets/SpaceAndCrafts/Prefabs/Inventions") >= 10 ? 22 : 0,
                (TypeExists("SpaceAndCrafts.AI.ScrapFloater") ? 10 : 0)
                    + (FileContains("BossSpectacleDirector") ? 10 : 0)
                    + (TypeExists("SpaceAndCrafts.Gameplay.InventionRemixDirector") ? 12 : 0),
                TypeExists("SpaceAndCrafts.Gameplay.InventionRemixDirector")
                    ? "Remix chains + craft novelty live; still want denser kingdom expression"
                    : "Hook is strong; needs denser expression in every kingdom",
                "Craft loop", "Teach pads", "Unique inventions", "Remix / combat novelty"));

            // Polish
            var hudWatermark = FileContainsExact(
                "Assets/SpaceAndCrafts/Scripts/UI/CollectibleHud.cs", "TEMP ART");
            list.Add(Score(
                "polish", "Polish", 97,
                FileContains("TenWorldsReadinessValidator") ? 16 : 0,
                FileContains("ArrivalPlayModeSmoke") ? 16 : 0,
                FileContains("World02PlayModeSmoke") ? 14 : 0,
                (!hudWatermark ? 38 : 6)
                    + (FileContains("HumanFeelSignOffMenu") || FileContains("Brief apex hang") ? 14 : 0),
                hudWatermark
                    ? "TEMP ART HUD watermark still present"
                    : "Smoke + feel polish live; commissioned art still pending",
                "Readiness validator", "Arrival smoke", "World02 smoke", "Feel / clean HUD"));

            // Commercial
            var authoredAssets = commissionedFbx + audioClips + animClips;
            var homePitch = TypeExists("SpaceAndCrafts.UI.HomeCommercialPitch");
            list.Add(Score(
                "commercial", "Commercial readiness", 97,
                Exists("Assets/SpaceAndCrafts/Scenes/Menus/HomeMenu.unity") ? 14 : 0,
                worldScenes >= 9 ? 14 : 0,
                authoredAssets >= 20 ? 46 : authoredAssets > 0 ? 22 : 0,
                (FileContains("QUALITY_SCORECARD") ? 12 : 0) + (homePitch ? 12 : 0),
                homePitch && authoredAssets >= 20
                    ? "Home pitch + asset banks; not yet a $50 Galaxy product"
                    : authoredAssets >= 20
                        ? "Asset banks exist; not yet a $50 Galaxy product"
                        : "Not a $50 Galaxy-class product yet",
                "Home menu", "10 worlds scaffold", "Authored assets", "Pitch / scorecard"));

            return list;
        }
