            var authored = CountAudioClips() > 0
                           || CountFiles("Assets/SpaceAndCrafts", "*.anim") > 0
                           || CountFiles("Assets/SpaceAndCrafts/Art/Commissioned", "*.fbx")
                           + CountFiles("Assets/SpaceAndCrafts/Art/Commissioned", "*.FBX") > 0;
            var ceiling = authored ? 98 : 70;
            var raw = Mathf.Clamp(a + b + c + d, 0, ceiling);
            var evidence = new List<string>();
            var parts = new[] { a, b, c, d };
            for (var i = 0; i < evidenceLabels.Length && i < parts.Length; i++)
            {
                evidence.Add($"{evidenceLabels[i]}:{(parts[i] > 0 ? "yes" : "no")}+{parts[i]}");
            }

            return new Pillar
            {
                Id = id,
                Label = label,
                Galaxy = galaxy,
                Score = raw,
                Blocker = blocker,
                Evidence = evidence
            };
        }

        private static int ComputeOverall(List<Pillar> pillars)
        {
            if (pillars.Count == 0) return 0;
            var sum = 0;
            for (var i = 0; i < pillars.Count; i++) sum += pillars[i].Score;
            return Mathf.RoundToInt(sum / (float)pillars.Count);
        }

        private static List<Pillar> FindLowest(List<Pillar> pillars, int n)
        {
            var copy = new List<Pillar>(pillars);
            copy.Sort((x, y) => x.Score.CompareTo(y.Score));
            if (copy.Count > n) copy.RemoveRange(n, copy.Count - n);
            return copy;
        }

        private static bool AllAtLeast(List<Pillar> pillars, int min)
        {
            for (var i = 0; i < pillars.Count; i++)
            {
                if (pillars[i].Score < min) return false;
            }

            return true;
        }

        private static void WriteJson(List<Pillar> pillars, int overall, bool humanFeel, List<Pillar> lowest)
        {
            EnsureLogsFolder();
            var sb = new StringBuilder();
            sb.AppendLine("{");
            sb.AppendLine($"  \"benchmark\": \"Super Mario Galaxy\",");
            sb.AppendLine($"  \"parityGate\": {GalaxyParity},");
            sb.AppendLine($"  \"overall\": {overall},");
            sb.AppendLine($"  \"humanFeelSignedOff\": {(humanFeel ? "true" : "false")},");
            sb.AppendLine($"  \"proxyCeiling\": {(CountAudioClips() > 0 ? 98 : 70)},");
            sb.AppendLine($"  \"auditedAt\": \"{DateTime.UtcNow:o}\",");
            sb.AppendLine("  \"nextFocus\": [");
            for (var i = 0; i < lowest.Count; i++)
            {
                sb.Append($"    \"{Escape(lowest[i].Label)}\"");
                sb.AppendLine(i < lowest.Count - 1 ? "," : "");
            }

            sb.AppendLine("  ],");
            sb.AppendLine("  \"pillars\": [");
            for (var i = 0; i < pillars.Count; i++)
            {
                var p = pillars[i];
                sb.AppendLine("    {");
                sb.AppendLine($"      \"id\": \"{p.Id}\",");
                sb.AppendLine($"      \"label\": \"{Escape(p.Label)}\",");
                sb.AppendLine($"      \"score\": {p.Score},");
                sb.AppendLine($"      \"galaxy\": {p.Galaxy},");
                sb.AppendLine($"      \"gap\": {p.Galaxy - p.Score},");
                sb.AppendLine($"      \"blocker\": \"{Escape(p.Blocker)}\",");
                sb.Append("      \"evidence\": [");
                for (var e = 0; e < p.Evidence.Count; e++)
                {
                    if (e > 0) sb.Append(", ");
                    sb.Append($"\"{Escape(p.Evidence[e])}\"");
                }

                sb.AppendLine("]");
                sb.Append("    }");
                sb.AppendLine(i < pillars.Count - 1 ? "," : "");
            }

            sb.AppendLine("  ]");
            sb.AppendLine("}");
            File.WriteAllText(JsonPath, sb.ToString());
        }

        private static void AppendHistory(List<Pillar> pillars, int overall, bool humanFeel, List<Pillar> lowest)
        {
            EnsureLogsFolder();
            var focus = lowest.Count > 0 ? lowest[0].Label : "n/a";
            var line =
                $"{{\"at\":\"{DateTime.UtcNow:o}\",\"overall\":{overall},\"humanFeel\":{(humanFeel ? "true" : "false")},\"next\":\"{Escape(focus)}\",\"pillars\":{{";
            for (var i = 0; i < pillars.Count; i++)
            {
                if (i > 0) line += ",";
                line += $"\"{pillars[i].Id}\":{pillars[i].Score}";
            }

            line += "}}\n";
            File.AppendAllText("Logs/quality-scorecard-history.jsonl", line);
        }

        private static void RefreshMarkdown(List<Pillar> pillars, int overall, bool humanFeel, List<Pillar> lowest)
        {
            if (!File.Exists(MdPath))
            {
                return;
            }

            var text = File.ReadAllText(MdPath);
            var table = new StringBuilder();
            table.AppendLine("| Pillar | SAC | Galaxy | Gap | Primary blocker |");
            table.AppendLine("|---|---:|---:|---:|---|");
            for (var i = 0; i < pillars.Count; i++)
            {
                var p = pillars[i];
                table.AppendLine($"| {p.Label} | {p.Score} | {p.Galaxy} | {p.Galaxy - p.Score} | {p.Blocker} |");
            }

            table.AppendLine($"| **Overall** | **{overall}** | **94** | **{94 - overall}** | Proxy average; human feel={(humanFeel ? "signed" : "open")} |");

            // Replace between "## Current scores" table header block and "`humanFeelSignedOff`"
            var startMark = "| Pillar | SAC | Galaxy | Gap | Primary blocker |";
            var endMark = "`humanFeelSignedOff`:";
            var start = text.IndexOf(startMark, StringComparison.Ordinal);
            var end = text.IndexOf(endMark, StringComparison.Ordinal);
            if (start >= 0 && end > start)
            {
                var before = text.Substring(0, start);
                var after = text.Substring(end);
                text = before + table + "\n" + $"`humanFeelSignedOff`: **{(humanFeel ? "true" : "false")}**\n\n---\n\n" +
                       StripDuplicateAfterHuman(after);
            }

            // Append changelog line
            var stamp = DateTime.UtcNow.ToString("yyyy-MM-dd");
            var focus = lowest.Count > 0 ? lowest[0].Label : "n/a";
            var changeLine = $"| {stamp} | {overall} | Auto-audit; next focus starts at {focus} |";
            if (!text.Contains(changeLine))
            {
                var changeHeader = "| Date | Overall | Notes |";
                var idx = text.IndexOf(changeHeader, StringComparison.Ordinal);
                if (idx >= 0)
                {
                    var lineEnd = text.IndexOf('\n', idx);
                    if (lineEnd > 0)
                    {
                        var second = text.IndexOf('\n', lineEnd + 1); // skip separator
                        if (second > 0)
                        {
                            text = text.Insert(second + 1, changeLine + "\n");
                        }
                    }
                }
            }

            // Next focus section
            var focusBuilder = new StringBuilder();
            focusBuilder.AppendLine("## Next focus (always lowest three)");
            focusBuilder.AppendLine();
