            var nl = after.IndexOf('\n');
            if (nl < 0) return after;
            var rest = after.Substring(nl + 1);
            // remove a following blank + --- block we re-add
            if (rest.StartsWith("\n---")) return rest;
            if (rest.StartsWith("---")) return rest;
            // If old content had **false** line already consumed partially, trim leading leftovers
            return rest;
