        private static void EnsureLogsFolder()
        {
            if (!Directory.Exists("Logs"))
            {
                Directory.CreateDirectory("Logs");
            }
        }

        private static bool Exists(string path) => File.Exists(path) || Directory.Exists(path);

        private static bool TypeExists(string fullName)
        {
            var guids = AssetDatabase.FindAssets("t:MonoScript");
            for (var i = 0; i < guids.Length; i++)
            {
                var path = AssetDatabase.GUIDToAssetPath(guids[i]);
                if (!path.Contains("SpaceAndCrafts")) continue;
                var script = AssetDatabase.LoadAssetAtPath<MonoScript>(path);
                var type = script != null ? script.GetClass() : null;
                if (type != null && type.FullName == fullName) return true;
            }

            // Fallback: filename match
            var leaf = fullName.Contains(".") ? fullName.Substring(fullName.LastIndexOf('.') + 1) : fullName;
            return FileContains($"class {leaf}");
        }

        private static bool FileContains(string token)
        {
            var root = "Assets/SpaceAndCrafts";
            if (!Directory.Exists(root)) return false;
            foreach (var file in Directory.GetFiles(root, "*.cs", SearchOption.AllDirectories))
            {
                try
                {
                    if (File.ReadAllText(file).IndexOf(token, StringComparison.Ordinal) >= 0) return true;
                }
                catch
                {
                    // ignore
                }
            }

            return false;
        }

        private static bool FileContainsExact(string path, string token)
        {
            if (!File.Exists(path)) return false;
            try
            {
                return File.ReadAllText(path).IndexOf(token, StringComparison.Ordinal) >= 0;
            }
            catch
            {
                return false;
            }
        }

        private static int CountFiles(string folder, string pattern)
        {
            if (!Directory.Exists(folder)) return 0;
            return Directory.GetFiles(folder, pattern, SearchOption.AllDirectories).Length;
        }

        private static int CountPrefabs(string folder)
        {
            return CountFiles(folder, "*.prefab");
        }

        private static int CountAudioClips()
        {
            return CountFiles("Assets", "*.wav")
                   + CountFiles("Assets", "*.ogg")
                   + CountFiles("Assets", "*.mp3")
                   + CountFiles("Assets", "*.aiff");
        }

        private static string Escape(string s) => (s ?? string.Empty).Replace("\\", "\\\\").Replace("\"", "\\\"");
    }
